    for (int i = 0; i < NN; i++) cid[i] = -1, rid[i] = -1;
    for (int i = 0; i < NN; i++) if (bd->b[i] == col && cid[i] < 0) {
        int nl; int libs[NN];
        int n = chain(bd, i, cst + pos, &nl, libs);
