static int key_alive(const Board *bd) {
    uint64_t h = bd->h | 1; int idx = (int)(h & (BC_SIZE - 1));
    if (bc_key[idx] == h) return bc_val[idx];
    int v = benson_keys(bd);
    bc_key[idx] = h; bc_val[idx] = v; return v;
