    prune_eye = pr;
    solver = sc; goal_live = (gs[0] == 'l');
    defender = goal_live ? solver : 3 - solver; attacker = 3 - defender;
    scanf("%d", &nkeys); for (int i = 0; i < nkeys; i++) scanf("%d", &keys[i]);
